import SwiftUI\n\nstruct WalletPaymentView: View {\n    @EnvironmentObject var authService: AuthService\n    @EnvironmentObject var paymentService: PaymentService\n    @State private var selectedTab = 0\n    @State private var depositAmount = \"\"\n    @State private var withdrawAmount = \"\"\n    @State private var selectedPaymentMethod: PaymentMethod = .creditCard\n    @State private var showingPaymentSheet = false\n    @State private var showingSuccess = false\n    @State private var successMessage = \"\"\n    \n    enum PaymentMethod: String, CaseIterable {\n        case creditCard = \"💳 Credit Card\"\n        case applePay = \"🍎 Apple Pay\"\n        case paypal = \"🅿️ PayPal\"\n        case skrill = \"💰 Skrill\"\n        case neteller = \"📱 Neteller\"\n        case bankTransfer = \"🏦 Bank Transfer\"\n    }\n    \n    var body: some View {\n        ZStack {\n            LinearGradient(\n                gradient: Gradient(colors: [.blue.opacity(0.1), .purple.opacity(0.1)]),\n                startPoint: .topLeading,\n                endPoint: .bottomTrailing\n            )\n            .ignoresSafeArea()\n            \n            VStack(spacing: 0) {\n                // Header\n                VStack(spacing: 12) {\n                    Text(\"💰 Wallet\")\n                        .font(.title)\n                        .fontWeight(.bold)\n                    Text(\"Current Balance: \\(authService.currentPlayer?.balance.asCurrency() ?? \"$0.00\")\")\n                        .font(.headline)\n                        .foregroundColor(.green)\n                }\n                .frame(maxWidth: .infinity)\n                .padding()\n                .background(Color.black.opacity(0.3))\n                \n                // Tab Selection\n                Picker(\"Transaction Type\", selection: $selectedTab) {\n                    Text(\"Deposit\").tag(0)\n                    Text(\"Withdraw\").tag(1)\n                    Text(\"History\").tag(2)\n                }\n                .pickerStyle(.segmented)\n                .padding()\n                \n                // Content\n                if selectedTab == 0 {\n                    depositView\n                } else if selectedTab == 1 {\n                    withdrawView\n                } else {\n                    transactionHistoryView\n                }\n                \n                Spacer()\n            }\n        }\n        .sheet(isPresented: $showingPaymentSheet) {\n            paymentProcessingSheet\n        }\n        .alert(\"Success\", isPresented: $showingSuccess) {\n            Button(\"OK\", role: .cancel) { }\n        } message: {\n            Text(successMessage)\n        }\n    }\n    \n    var depositView: some View {\n        ScrollView {\n            VStack(spacing: 20) {\n                // Amount Input\n                VStack(alignment: .leading, spacing: 8) {\n                    Text(\"Deposit Amount\")\n                        .font(.headline)\n                        .foregroundColor(.white)\n                    \n                    HStack {\n                        Text(\"$\")\n                            .font(.headline)\n                        TextField(\"Enter amount\", text: $depositAmount)\n                            .keyboardType(.decimalPad)\n                            .textFieldStyle(.roundedBorder)\n                    }\n                }\n                .padding()\n                .background(Color.black.opacity(0.2))\n                .cornerRadius(12)\n                \n                // Quick Amount Buttons\n                VStack(spacing: 8) {\n                    Text(\"Quick Amount\")\n                        .font(.headline)\n                        .foregroundColor(.white)\n                        .frame(maxWidth: .infinity, alignment: .leading)\n                    \n                    let amounts = [50, 100, 250, 500]\n                    VStack(spacing: 8) {\n                        HStack(spacing: 8) {\n                            ForEach(Array(amounts.prefix(2)), id: \\.self) { amount in\n                                quickAmountButton(amount)\n                            }\n                        }\n                        HStack(spacing: 8) {\n                            ForEach(Array(amounts.suffix(2)), id: \\.self) { amount in\n                                quickAmountButton(amount)\n                            }\n                        }\n                    }\n                }\n                .padding()\n                .background(Color.black.opacity(0.2))\n                .cornerRadius(12)\n                \n                // Payment Method Selection\n                VStack(alignment: .leading, spacing: 12) {\n                    Text(\"Payment Method\")\n                        .font(.headline)\n                        .foregroundColor(.white)\n                    \n                    ForEach(PaymentMethod.allCases, id: \\.self) { method in\n                        Button(action: { selectedPaymentMethod = method }) {\n                            HStack {\n                                Text(method.rawValue)\n                                Spacer()\n                                if selectedPaymentMethod == method {\n                                    Image(systemName: \"checkmark.circle.fill\")\n                                        .foregroundColor(.green)\n                                }\n                            }\n                            .padding()\n                            .background(selectedPaymentMethod == method ? Color.green.opacity(0.2) : Color.black.opacity(0.2))\n                            .cornerRadius(8)\n                            .foregroundColor(.white)\n                        }\n                    }\n                }\n                .padding()\n                .background(Color.black.opacity(0.2))\n                .cornerRadius(12)\n                \n                // Deposit Button\n                Button(action: processDeposit) {\n                    Text(\"DEPOSIT NOW\")\n                        .font(.headline)\n                        .fontWeight(.bold)\n                        .foregroundColor(.black)\n                        .frame(maxWidth: .infinity)\n                        .padding()\n                        .background(Color.yellow)\n                        .cornerRadius(12)\n                }\n                .disabled(depositAmount.isEmpty || paymentService.isProcessing)\n                \n                if paymentService.isProcessing {\n                    ProgressView()\n                        .tint(.yellow)\n                }\n                \n                if let error = paymentService.errorMessage {\n                    Text(\"❌ \\(error)\")\n                        .foregroundColor(.red)\n                        .font(.caption)\n                }\n            }\n            .padding()\n        }\n    }\n    \n    var withdrawView: some View {\n        ScrollView {\n            VStack(spacing: 20) {\n                // Amount Input\n                VStack(alignment: .leading, spacing: 8) {\n                    Text(\"Withdrawal Amount\")\n                        .font(.headline)\n                        .foregroundColor(.white)\n                    \n                    HStack {\n                        Text(\"$\")\n                            .font(.headline)\n                        TextField(\"Enter amount\", text: $withdrawAmount)\n                            .keyboardType(.decimalPad)\n                            .textFieldStyle(.roundedBorder)\n                    }\n                }\n                .padding()\n                .background(Color.black.opacity(0.2))\n                .cornerRadius(12)\n                \n                // Withdrawal Method Selection\n                VStack(alignment: .leading, spacing: 12) {\n                    Text(\"Withdrawal Method\")\n                        .font(.headline)\n                        .foregroundColor(.white)\n                    \n                    ForEach(PaymentMethod.allCases, id: \\.self) { method in\n                        Button(action: { selectedPaymentMethod = method }) {\n                            HStack {\n                                Text(method.rawValue)\n                                Spacer()\n                                if selectedPaymentMethod == method {\n                                    Image(systemName: \"checkmark.circle.fill\")\n                                        .foregroundColor(.green)\n                                }\n                            }\n                            .padding()\n                            .background(selectedPaymentMethod == method ? Color.green.opacity(0.2) : Color.black.opacity(0.2))\n                            .cornerRadius(8)\n                            .foregroundColor(.white)\n                        }\n                    }\n                }\n                .padding()\n                .background(Color.black.opacity(0.2))\n                .cornerRadius(12)\n                \n                // Bank Details (if bank transfer selected)\n                if selectedPaymentMethod == .bankTransfer {\n                    VStack(alignment: .leading, spacing: 12) {\n                        Text(\"Bank Account Details\")\n                            .font(.headline)\n                            .foregroundColor(.white)\n                        \n                        VStack(alignment: .leading, spacing: 8) {\n                            Text(\"Account Name\")\n                                .font(.caption)\n                                .foregroundColor(.white.opacity(0.7))\n                            TextField(\"Your name\", text: .constant(\"\"))\n                                .textFieldStyle(.roundedBorder)\n                        }\n                        \n                        VStack(alignment: .leading, spacing: 8) {\n                            Text(\"Account Number\")\n                                .font(.caption)\n                                .foregroundColor(.white.opacity(0.7))\n                            TextField(\"Account number\", text: .constant(\"\"))\n                                .textFieldStyle(.roundedBorder)\n                        }\n                    }\n                    .padding()\n                    .background(Color.black.opacity(0.2))\n                    .cornerRadius(12)\n                }\n                \n                // Withdrawal Button\n                Button(action: processWithdrawal) {\n                    Text(\"REQUEST WITHDRAWAL\")\n                        .font(.headline)\n                        .fontWeight(.bold)\n                        .foregroundColor(.black)\n                        .frame(maxWidth: .infinity)\n                        .padding()\n                        .background(Color.yellow)\n                        .cornerRadius(12)\n                }\n                .disabled(withdrawAmount.isEmpty || paymentService.isProcessing)\n                \n                if paymentService.isProcessing {\n                    ProgressView()\n                        .tint(.yellow)\n                }\n                \n                if let error = paymentService.errorMessage {\n                    Text(\"❌ \\(error)\")\n                        .foregroundColor(.red)\n                        .font(.caption)\n                }\n            }\n            .padding()\n        }\n    }\n    \n    var transactionHistoryView: some View {\n        ScrollView {\n            VStack(spacing: 12) {\n                if paymentService.transactionHistory.isEmpty {\n                    VStack(spacing: 12) {\n                        Text(\"📭\")\n                            .font(.system(size: 48))\n                        Text(\"No transactions yet\")\n                            .foregroundColor(.white.opacity(0.7))\n                    }\n                    .frame(maxHeight: .infinity)\n                    .padding()\n                } else {\n                    ForEach(paymentService.transactionHistory.reversed()) { payment in\n                        HStack {\n                            VStack(alignment: .leading, spacing: 4) {\n                                Text(payment.method.rawValue)\n                                    .fontWeight(.semibold)\n                                    .foregroundColor(.white)\n                                Text(payment.timestamp.formatted(date: .abbreviated, time: .shortened))\n                                    .font(.caption)\n                                    .foregroundColor(.white.opacity(0.6))\n                            }\n                            Spacer()\n                            VStack(alignment: .trailing, spacing: 4) {\n                                Text(payment.amount.asCurrency())\n                                    .fontWeight(.bold)\n                                    .foregroundColor(.green)\n                                Text(payment.status.rawValue)\n                                    .font(.caption)\n                                    .foregroundColor(payment.status == .completed ? .green : .orange)\n                            }\n                        }\n                        .padding()\n                        .background(Color.black.opacity(0.3))\n                        .cornerRadius(8)\n                    }\n                }\n            }\n            .padding()\n        }\n    }\n    \n    var paymentProcessingSheet: some View {\n        VStack(spacing: 20) {\n            Text(\"Processing Payment\")\n                .font(.headline)\n            \n            ProgressView()\n                .tint(.yellow)\n            \n            Text(\"Please wait while we process your transaction...\")\n                .font(.caption)\n                .foregroundColor(.white.opacity(0.7))\n        }\n        .padding(40)\n        .frame(maxWidth: .infinity, maxHeight: .infinity)\n        .background(Color.black.opacity(0.8))\n    }\n    \n    private func quickAmountButton(_ amount: Int) -> some View {\n        Button(action: { depositAmount = String(amount) }) {\n            Text(\"$\\(amount)\")\n                .fontWeight(.semibold)\n                .foregroundColor(.black)\n                .frame(maxWidth: .infinity)\n                .padding()\n                .background(Color.yellow)\n                .cornerRadius(8)\n        }\n    }\n    \n    private func processDeposit() {\n        guard let amount = Double(depositAmount), amount > 0 else {\n            paymentService.errorMessage = \"Invalid amount\"\n            return\n        }\n        \n        showingPaymentSheet = true\n        \n        switch selectedPaymentMethod {\n        case .creditCard:\n            paymentService.processStripePayment(amount: amount, cardToken: \"tok_test\") { success, error in\n                showingPaymentSheet = false\n                if success {\n                    successMessage = \"Deposit of \\(amount.asCurrency()) successful!\"\n                    showingSuccess = true\n                    depositAmount = \"\"\n                    authService.updateBalance(newBalance: (authService.currentPlayer?.balance ?? 0) + amount)\n                }\n            }\n        case .applePay:\n            paymentService.processApplePayment(amount: amount) { success, error in\n                showingPaymentSheet = false\n                if success {\n                    successMessage = \"Deposit of \\(amount.asCurrency()) successful!\"\n                    showingSuccess = true\n                    depositAmount = \"\"\n                    authService.updateBalance(newBalance: (authService.currentPlayer?.balance ?? 0) + amount)\n                }\n            }\n        case .paypal:\n            paymentService.processPayPalPayment(amount: amount) { success, error in\n                showingPaymentSheet = false\n                if success {\n                    successMessage = \"Deposit of \\(amount.asCurrency()) successful!\"\n                    showingSuccess = true\n                    depositAmount = \"\"\n                    authService.updateBalance(newBalance: (authService.currentPlayer?.balance ?? 0) + amount)\n                }\n            }\n        case .skrill:\n            paymentService.processSkrillPayment(amount: amount, email: authService.currentPlayer?.email ?? \"\") { success, error in\n                showingPaymentSheet = false\n                if success {\n                    successMessage = \"Deposit of \\(amount.asCurrency()) successful!\"\n                    showingSuccess = true\n                    depositAmount = \"\"\n                    authService.updateBalance(newBalance: (authService.currentPlayer?.balance ?? 0) + amount)\n                }\n            }\n        case .neteller:\n            paymentService.processNetellerPayment(amount: amount, email: authService.currentPlayer?.email ?? \"\") { success, error in\n                showingPaymentSheet = false\n                if success {\n                    successMessage = \"Deposit of \\(amount.asCurrency()) successful!\"\n                    showingSuccess = true\n                    depositAmount = \"\"\n                    authService.updateBalance(newBalance: (authService.currentPlayer?.balance ?? 0) + amount)\n                }\n            }\n        case .bankTransfer:\n            paymentService.initiateBankTransfer(amount: amount, accountName: \"\", accountNumber: \"\") { success, error in\n                showingPaymentSheet = false\n                if success {\n                    successMessage = \"Bank transfer initiated. It may take 1-3 business days.\"\n                    showingSuccess = true\n                    depositAmount = \"\"\n                }\n            }\n        }\n    }\n    \n    private func processWithdrawal() {\n        guard let amount = Double(withdrawAmount), amount > 0 else {\n            paymentService.errorMessage = \"Invalid amount\"\n            return\n        }\n        \n        guard let currentBalance = authService.currentPlayer?.balance, amount <= currentBalance else {\n            paymentService.errorMessage = \"Insufficient balance\"\n            return\n        }\n        \n        showingPaymentSheet = true\n        \n        paymentService.requestWithdrawal(amount: amount, method: selectedPaymentMethod.toPaymentMethod(), accountDetails: [:]) { success, error in\n            showingPaymentSheet = false\n            if success {\n                successMessage = \"Withdrawal request of \\(amount.asCurrency()) submitted!\"\n                showingSuccess = true\n                withdrawAmount = \"\"\n                authService.updateBalance(newBalance: currentBalance - amount)\n            }\n        }\n    }\n}\n\nextension WalletPaymentView.PaymentMethod {\n    func toPaymentMethod() -> Payment.PaymentMethod {\n        switch self {\n        case .creditCard: return .creditCard\n        case .applePay: return .applePay\n        case .paypal: return .paypal\n        case .skrill: return .skrill\n        case .neteller: return .neteller\n        case .bankTransfer: return .bankTransfer\n        }\n    }\n}\n\n#Preview {\n    WalletPaymentView()\n        .environmentObject(AuthService.shared)\n        .environmentObject(PaymentService.shared)\n        .preferredColorScheme(.dark)\n}\n